-- =====================================================================
-- Recicle Floripa — Catálogo oficial de resíduos (IBAMA)
-- Fonte: Lista Brasileira de Resíduos Sólidos, IN IBAMA nº 13/2012
--        (D.O.U. Seção 1, nº 245, 20/12/2012)
-- Rode no SQL Editor do Neon DEPOIS do schema.sql.
-- =====================================================================

-- Parte 1: estrutura --------------------------------------------------
-- Hierarquia do código IBAMA:  "15" capítulo > "15 01" subcapítulo > "15 01 02" resíduo
CREATE TABLE IF NOT EXISTS catalogo_residuos (
  codigo            VARCHAR(8)  PRIMARY KEY,
  nivel             SMALLINT    NOT NULL CHECK (nivel BETWEEN 1 AND 3),
  codigo_pai        VARCHAR(8)  REFERENCES catalogo_residuos(codigo),
  descricao         TEXT        NOT NULL,
  perigoso          BOOLEAN     NOT NULL DEFAULT FALSE,
  unidade           VARCHAR(5),
  -- campos preenchidos pelo grupo (não fazem parte da lista do IBAMA):
  categoria_app     VARCHAR(40),   -- mesma categoria que a IA devolve
  material_ecoponto VARCHAR(40),   -- mesmo texto usado em ecopontos.materiais
  nomes_populares   TEXT           -- termos para a busca manual no app
);

CREATE INDEX IF NOT EXISTS idx_catalogo_categoria ON catalogo_residuos (categoria_app);

-- Parte 2: dados oficiais do IBAMA (1010 registros) ----------------------

-- Parte 3: classificação do grupo (itens do dia a dia) ----------------
-- Liga o código oficial às categorias do app, aos ecopontos e à busca.
